-- ═══════════════════════════════════════════════════════════════════════════
-- Migration 013: Features table + data
-- Source: zeach-brains/zeach-feature-modules/*.json
--
-- TABLE COLUMNS:
--   feature_id  — unique key matching feature_brain.feature_id
--   label       — display text  ← feature_brain.feature_name
--   description — short text    ← feature_brain.description
--   icon        — Lucide icon name (kebab-case), assigned per feature
--   archetypes  — text[]  empty = universal (shown for ALL products)
--   brain       — full feature module JSON
--   sort_order  — display order
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

-- ── Table ────────────────────────────────────────────────────────────────────
-- Create if not exists, then patch any missing columns added in this migration.

CREATE TABLE IF NOT EXISTS public.features (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  feature_id  text        NOT NULL UNIQUE,
  label       text        NOT NULL,
  icon        text,
  archetypes  text[]      NOT NULL DEFAULT '{}',
  sort_order  int         NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- Add new columns if the table already existed without them
ALTER TABLE public.features
  ADD COLUMN IF NOT EXISTS description text,
  ADD COLUMN IF NOT EXISTS brain       jsonb NOT NULL DEFAULT '{}';

-- ── RLS ──────────────────────────────────────────────────────────────────────

ALTER TABLE public.features ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "features are publicly readable" ON public.features;
CREATE POLICY "features are publicly readable"
  ON public.features FOR SELECT USING (true);

-- ── Data ─────────────────────────────────────────────────────────────────────
-- archetypes is '{}' (empty) for all current features = universal.
-- Add rows with non-empty archetypes for product-specific features in future.

TRUNCATE TABLE public.features RESTART IDENTITY;

INSERT INTO public.features (feature_id, label, description, icon, archetypes, brain, sort_order)
VALUES
  ('analytics_dashboard', 'Analytics / Dashboard', 'Data visualisation — KPI cards, charts, tables, and exportable reports.', 'bar-chart-2', '{}', '{"feature_id":"analytics_dashboard","feature_name":"Analytics / Dashboard","description":"Data visualisation — KPI cards, charts, tables, and exportable reports.","screens_added":[{"id":"analytics_home","name":"Analytics Overview","purpose":"KPI cards + summary charts at a glance"},{"id":"report_detail","name":"Report Detail","purpose":"Deep dive into a specific metric or time range"},{"id":"data_table","name":"Data Table","purpose":"Tabular data with sort, filter, and export"}],"entities_added":["Metric","Report","DataPoint","DateRange"],"flows_added":["View dashboard → spot metric → tap → drill into report detail","Select date range → data updates → export as CSV or PDF","Set metric alert → threshold fires → notification sent → view in dashboard"],"interaction_patterns":["KPI cards animate in on load — counter counts up to current value","Chart tap — shows exact value tooltip at tapped point","Date range picker — presets (7d, 30d, 90d, custom) as chip row","Table sort — tap column header, tap again to reverse","Export button always accessible — CSV and PDF","Empty state on no data — clear explanation, not just a blank chart"],"generates_images":false,"error_flows":[{"trigger":"Data fails to load for a metric","ui":"Individual chart shows error state inline — not full page error. Icon: warning triangle. Message: ''Could not load [metric name]''. Retry button per chart. Other charts unaffected. Partial dashboard always better than full failure."},{"trigger":"Date range returns no data","ui":"Chart area shows: ''No data for this period''. Previous period CTA: ''Try last 30 days''. Do not show empty axes — replace with message. Suggest date ranges that do have data if known."},{"trigger":"Export fails","ui":"Toast: ''Export failed — please try again''. If large export: ''File is too large to export at once — try a shorter date range''. Progress indicator on large exports. Never leave user waiting with no feedback."},{"trigger":"Real-time data stream disconnects","ui":"Last updated timestamp shown on live metrics. Amber badge: ''Live data paused''. Auto-reconnect in background. On reconnect: refresh all metrics simultaneously, not one by one."},{"trigger":"Metric alert threshold fires but notification fails to deliver","ui":"Alert still recorded in notification centre. Shown as unread on next app open with timestamp of when threshold was breached. Never silently miss an alert."}],"edge_cases":[{"case":"All metrics are zero (new account, no activity)","ui":"Show metrics at zero with onboarding guidance instead of empty charts. ''Your data will appear here once you have [X] activity''. Do not show flat zero lines on charts — show empty state illustration instead."},{"case":"Single data point in a time series chart","ui":"Show as a single dot, not a line. Horizontal reference line at value. Label with date and value. Never draw a line chart with one point — it implies trend where there is none."},{"case":"Metric value exceeds chart scale dramatically (spike)","ui":"Auto-scale Y axis to include spike. Label the spike point with value and date. Option to ''Exclude outlier'' to see underlying trend. Never clip data off the chart."},{"case":"User changes date range while data is still loading","ui":"Cancel previous request immediately. Start new request for new date range. Never show mixed data from two different date ranges."},{"case":"Comparison period has different number of days (e.g. Feb vs March)","ui":"Normalise to daily averages for comparison, not raw totals. Label clearly: ''Per day average''. Never compare 28-day February total directly to 31-day March total without disclosure."},{"case":"Negative metric value (returns exceed sales, refunds exceed revenue)","ui":"Show negative values in red. Allow Y axis to go below zero. Never hide negative values or floor at zero. Negative data is valid and important."}]}'::jsonb, 1),
  ('authentication', 'Authentication', 'User identity — signup, login, session management, and account recovery.', 'lock', '{}', '{"feature_id":"authentication","feature_name":"Authentication","description":"User identity — signup, login, session management, and account recovery.","screens_added":[{"id":"splash","name":"Splash / Launch","purpose":"Auth state check — redirect to login or home"},{"id":"login","name":"Login","purpose":"Email/password, social login, biometric"},{"id":"signup","name":"Sign Up","purpose":"Account creation — email or social"},{"id":"verify_email","name":"Verify Email","purpose":"OTP or magic link confirmation"},{"id":"forgot_password","name":"Forgot Password","purpose":"Password reset via email"},{"id":"onboarding_profile","name":"Profile Setup","purpose":"Name, avatar, preferences after signup"}],"entities_added":["User","Session","OAuthProvider","VerificationToken"],"flows_added":["Email signup → verify email → profile setup → home","Social login (Google/Apple) → permissions → home","Login → biometric or PIN → home","Forgot password → email sent → reset link → new password → login"],"interaction_patterns":["Biometric login — Face ID or fingerprint on return visit","Social login buttons — Google and Apple always above the fold","OTP input — 6 digits, auto-advance on each digit","Magic link — single CTA, no password required","Session timeout warning — modal with extend or logout"],"generates_images":false,"error_flows":[{"trigger":"Wrong password entered","ui":"Inline error below password field: ''Incorrect password''. Field border red. Password field cleared. After 3 failed attempts: ''Too many attempts — try again in 30 seconds''. Countdown timer shown. Never lock permanently on first session."},{"trigger":"Email not registered","ui":"Inline error: ''No account found with this email''. Do NOT confirm whether email exists if security-sensitive — show generic ''Email or password incorrect'' instead. Context-dependent."},{"trigger":"OTP expired or incorrect","ui":"Red border on OTP input. Message: ''Invalid or expired code''. Resend CTA appears immediately. Countdown resets. Previous entry cleared. Never leave user stranded without resend option."},{"trigger":"Social login fails (Google/Apple)","ui":"Toast: ''Sign in with [Provider] failed''. Fallback CTA: ''Continue with email instead''. Never show raw OAuth error codes to user. Log internally."},{"trigger":"Session expired mid-use","ui":"Modal overlay: ''Your session has expired''. CTA: ''Log in again''. Preserve current page state where possible — user returns to same screen after re-auth. Never silently redirect to home."},{"trigger":"Account already exists with same email","ui":"On signup: ''An account with this email already exists''. CTA: ''Log in instead''. Pre-fill email on login screen. Do not allow duplicate accounts."}],"edge_cases":[{"case":"User switches between social and email login for same account","ui":"Detect email match — prompt to link accounts: ''You previously signed in with Google. Link your accounts?'' Confirm before merging. Never create duplicate account silently."},{"case":"Biometric not set up on device","ui":"Biometric option hidden — never shown as disabled or greyed. Fall back to PIN or password without mentioning biometric unavailability."},{"case":"User enters email with typo (e.g. .con instead of .com)","ui":"Inline suggestion: ''Did you mean [corrected email]?'' Shown immediately on blur, not on submit. Tap to accept correction."},{"case":"Password reset link already used","ui":"Show: ''This reset link has already been used or has expired''. CTA: ''Request a new reset link''. Never show a blank or error page."},{"case":"User is already logged in on another device","ui":"On login: ''You are already signed in on another device. Continue here?'' Options: ''Sign in here'' (logs out other device) or ''Cancel''. Make the consequence explicit."},{"case":"Magic link clicked on different device than requested","ui":"Show warning: ''This link was opened on a different device''. Options: ''Continue anyway'' or ''Request a new link''. Do not auto-approve cross-device without acknowledgement."}]}'::jsonb, 2),
  ('chat_messaging', 'Chat / Messaging', 'In-app real-time messaging between users, providers, or support.', 'message-circle', '{}', '{"feature_id":"chat_messaging","feature_name":"Chat / Messaging","description":"In-app real-time messaging between users, providers, or support.","screens_added":[{"id":"inbox","name":"Inbox","purpose":"All conversations — unread indicator, last message preview"},{"id":"chat_thread","name":"Chat Thread","purpose":"Full conversation with message input"},{"id":"new_message","name":"New Message","purpose":"Start conversation — contact search"},{"id":"chat_media","name":"Shared Media","purpose":"All files and images shared in conversation"}],"entities_added":["Conversation","Message","Attachment","Reaction"],"flows_added":["Select contact → open thread → send message → receive reply","Receive notification → tap → open thread → reply","Long press message → react / reply / copy / delete"],"interaction_patterns":["Typing indicator — animated dots while other user types","Read receipts — single tick sent, double tick delivered, filled = read","Swipe right on message to reply — quoted message appears in input","Message bubbles — sent right, received left","Long press for context menu — react, reply, copy, delete","Unread count badge on inbox icon"],"generates_images":false,"error_flows":[{"trigger":"Message fails to send","ui":"Message bubble shows red warning icon on right edge. Tap: ''Message failed to send — tap to retry''. Options: Retry, Delete message. Message remains in thread at correct position. Never silently drop. Retry preserves original timestamp."},{"trigger":"File or image fails to send","ui":"Attachment thumbnail shows red error overlay. Message: ''File failed to send''. File size shown. Options: Retry, Remove. Never show broken image icon in thread permanently."},{"trigger":"User blocked attempts to send message","ui":"Input disabled with message: ''You can no longer message this person''. No toast — persistent state shown in thread header. Do not reveal if user was blocked vs account deactivated."},{"trigger":"Message delivery to group fails for some members","ui":"Delivery receipt shows partial: ''Delivered to 4 of 6''. Tap to see which members. Failed members shown with retry per member option. Never show as fully delivered when not."},{"trigger":"Real-time connection drops mid-conversation","ui":"Top of chat banner: ''Reconnecting...''. Input disabled during reconnect. Auto-reconnect in background. On reconnect: load missed messages automatically. Banner disappears without user action."},{"trigger":"Message content flagged by moderation","ui":"Message shows ''Message removed'' placeholder in thread. Sender notified privately: ''Your message was removed — [reason]''. Never silently delete without sender notification."}],"edge_cases":[{"case":"User sends message to themselves","ui":"Allow it — useful as personal notes. Show ''Note to self'' label in conversation list. No read receipt shown (would be confusing). No typing indicator."},{"case":"Very long message (1000+ characters)","ui":"Show first 300 characters with ''Show more'' inline. Full message in thread on expand. Search indexes full content. Never truncate in storage."},{"case":"Message sent in wrong conversation","ui":"Short window (5-10 seconds) to unsend — ''Undo send'' toast appears immediately after send. After window: message can be deleted from sender''s view only — recipients see ''Message deleted''."},{"case":"Group chat with only one remaining member (all others left)","ui":"Show banner: ''You are the only member of this group''. Options: ''Leave group'' or ''Invite people''. Input remains active — allow personal notes use case."},{"case":"Message received while device is offline","ui":"Push notification queued. On reconnect: messages delivered in order with original timestamps. Badge count accurate. No duplicate notifications."},{"case":"User attempts to re-add a contact they previously blocked","ui":"Confirm step: ''You previously blocked [name]. Unblocking will allow them to message you again''. Explicit confirmation required. Previous message history restored."}]}'::jsonb, 3),
  ('file_upload', 'File Upload', 'User-generated file and media upload — images, documents, and attachments.', 'upload', '{}', '{"feature_id":"file_upload","feature_name":"File Upload","description":"User-generated file and media upload — images, documents, and attachments.","screens_added":[{"id":"file_picker","name":"File Picker","purpose":"Select files from device, camera, or cloud"},{"id":"upload_progress","name":"Upload Progress","purpose":"Upload status with progress indicator"},{"id":"file_library","name":"File Library","purpose":"All uploaded files — browse, preview, delete"}],"entities_added":["File","Upload","MediaAsset"],"flows_added":["Tap upload → pick from camera/gallery/files → preview → confirm → upload → success","Drag and drop file onto upload zone → progress bar → file available","View file library → tap file → preview → share or delete"],"interaction_patterns":["Drag and drop on desktop — dotted border animates on hover","Upload progress ring on file thumbnail — fills as upload completes","Camera vs gallery vs files — three options always shown, never assume","File type validation — show error inline before upload attempt","Retry button on failed upload — never silent failure","Preview before confirm — user sees what they''re uploading"],"generates_images":false,"error_flows":[{"trigger":"File exceeds size limit","ui":"Inline error before upload attempt: ''File too large — maximum [X]MB''. Size of selected file shown. Suggestion: compress or use a different format. Never start upload then fail at 90%."},{"trigger":"File type not supported","ui":"Inline error: ''File type not supported — please use [accepted formats]''. Show accepted formats as chips. Never show raw MIME type to user. Fail immediately on selection, not on upload."},{"trigger":"Upload fails mid-way","ui":"Progress bar stops. Red state: ''Upload interrupted at [X]%''. Retry button. Option to resume if server supports resumable uploads. Other uploads in queue unaffected. Partial upload cleaned up on server."},{"trigger":"Storage quota exceeded","ui":"Before upload: check quota. If insufficient: ''You have used [X]GB of your [Y]GB limit''. CTA: ''Manage storage'' or ''Upgrade plan''. Never start upload that will fail due to quota."},{"trigger":"File fails virus/malware scan","ui":"File removed from queue. Message: ''This file could not be uploaded — it may contain harmful content''. Generic message only — never reveal scan details. Other files in batch unaffected."},{"trigger":"Duplicate file detected","ui":"Warning before upload: ''A file with this name already exists''. Options: ''Replace existing'', ''Keep both'' (auto-rename), ''Cancel''. Default: Keep both. Never silently overwrite."}],"edge_cases":[{"case":"User uploads same file twice in same session","ui":"Detect duplicate by name and size hash. Warn: ''This file has already been uploaded in this session''. Option to proceed or cancel. Never silently upload twice."},{"case":"Batch upload where some succeed and some fail","ui":"Show per-file status: green check for success, red X for failure. Summary: ''4 of 6 files uploaded successfully''. Retry failed files individually. Never report partial batch as full success."},{"case":"File name contains special characters or very long name","ui":"Sanitise file name silently for storage. Display original name to user. Never expose internal sanitised name. Long names truncated in UI with full name in tooltip."},{"case":"Upload initiated but user closes browser or navigates away","ui":"Show warning: ''Upload in progress — leaving this page will cancel the upload''. If PWA or native: continue upload in background. Web: warn and let user decide."},{"case":"Camera upload on mobile — very large raw photo","ui":"Auto-compress before upload if file exceeds limit. Show: ''Image compressed for upload — original quality preserved on device''. Compression settings configurable in settings."},{"case":"PDF upload with password protection","ui":"Detect password-protected PDF. Show: ''This PDF is password protected and cannot be previewed''. Still allow upload if file type is accepted. Note in file library."}]}'::jsonb, 4),
  ('maps_location', 'Maps / Location', 'Location awareness — map views, proximity search, directions, and live tracking.', 'map-pin', '{}', '{"feature_id":"maps_location","feature_name":"Maps / Location","description":"Location awareness — map views, proximity search, directions, and live tracking.","screens_added":[{"id":"map_view","name":"Map View","purpose":"Full map with pins for relevant entities"},{"id":"location_picker","name":"Location Picker","purpose":"User selects or confirms their location"},{"id":"nearby_results","name":"Nearby Results","purpose":"List of entities sorted by proximity"},{"id":"live_tracking","name":"Live Tracking","purpose":"Real-time position of driver, delivery, or provider"}],"entities_added":["Location","Pin","Route","TrackingSession"],"flows_added":["Enable location → map loads at current position → browse nearby pins → tap pin → detail","Search location → drop pin → confirm → use as address","Order placed → tracking screen opens → driver moves on map → arrival"],"interaction_patterns":["Map pins cluster at low zoom — expand on zoom in","Current location button — always visible, tapping re-centres map","Detail sheet slides up from bottom — map stays visible behind","Live tracking dot pulses — indicates real-time movement","ETA chip always visible on tracking screen","Location permission prompt — explain why before requesting"],"generates_images":false,"error_flows":[{"trigger":"Location permission denied","ui":"Map loads centred on default city or last known location. Banner: ''Enable location to see places near you''. CTA: direct link to device settings. Search still fully functional. Never block app usage."},{"trigger":"GPS signal weak or unavailable","ui":"Location dot shows with accuracy ring — larger ring = less accurate. Banner: ''Location accuracy is low''. Indoor location note if relevant. Never show false precision."},{"trigger":"Map tiles fail to load (offline or CDN failure)","ui":"Show cached tiles for last viewed area if available. Grey placeholder for uncached areas with grid lines. Message: ''Map tiles unavailable — check your connection''. Search and pins still functional."},{"trigger":"Directions request fails","ui":"Message: ''Could not calculate route''. Retry button. Fallback: ''Open in Maps'' — opens device native maps app with same destination. Never strand user without navigation option."},{"trigger":"Live tracking connection drops","ui":"Last known position shown with timestamp: ''Last updated 2 mins ago''. Pulsing amber dot instead of live green. Auto-reconnects in background. Never show stale position as live."},{"trigger":"Place data not found or outdated","ui":"Show: ''Limited information available for this place''. Display what is known. ''Suggest an edit'' CTA. Never show completely blank place detail screen."}],"edge_cases":[{"case":"User is at exact boundary of two regions/zones","ui":"Assign to nearest centroid — never show both zones simultaneously. Do not ask user to choose. Log boundary case for data improvement."},{"case":"User denies location then later grants it","ui":"Map immediately re-centres on actual location when permission granted. No restart required. Smooth transition — fly-to animation to actual location."},{"case":"Multiple pins stacked at same coordinates","ui":"Show cluster circle with count. Tap to zoom in and separate. At max zoom: show stacked list sheet from bottom with all places at that location."},{"case":"User location in a country with map data restrictions","ui":"Show best available data without exposing restriction reason. Never show ''Content not available in your region'' — show what is available."},{"case":"Offline navigation — route calculated but data changes en route","ui":"Offline route followed as downloaded. If recalculation needed and no connection: show ''Route may be outdated'' banner. Continue with last known route. Do not stop navigation."},{"case":"Very dense urban area — hundreds of pins visible","ui":"Cluster aggressively at low zoom. Max 20 individual pins visible at any zoom level. Performance: never render more than 50 DOM pin elements — use canvas for overflow."}]}'::jsonb, 5),
  ('notifications', 'Notifications', 'Push and in-app notification system with preferences management.', 'bell', '{}', '{"feature_id":"notifications","feature_name":"Notifications","description":"Push and in-app notification system with preferences management.","screens_added":[{"id":"notifications_feed","name":"Notifications","purpose":"All activity — categorised, unread indicator"},{"id":"notification_settings","name":"Notification Settings","purpose":"Toggle per notification type and delivery channel"}],"entities_added":["Notification","NotificationPreference"],"flows_added":["Event triggers notification → push sent → user taps → deep links to relevant screen","User opens notification settings → toggles types → selects channels (push/email/SMS)"],"interaction_patterns":["Push notification tap deep links directly to the relevant screen — never to notification list","Unread dot on notification icon — disappears on open","Mark all read — single action","Notification categories — activity, updates, promotions — separately toggleable","Notification permission prompt — shown after first meaningful action, never on launch"],"generates_images":false,"error_flows":[{"trigger":"Push notification permission denied by user","ui":"No prompt re-shown for 30 days after denial. In-app notification centre still works fully. Settings screen shows ''Enable push notifications'' card with direct link to device settings. Never nag."},{"trigger":"Notification deep link points to deleted content","ui":"Navigate to parent screen instead of crashing. Show toast: ''This content is no longer available''. Never show blank screen or error code. Example: notification for deleted post → open feed."},{"trigger":"Notification delivery fails silently","ui":"In-app notification centre always shows all notifications regardless of push delivery status. Badge count reflects unread in-app count, not push delivery count."},{"trigger":"Batch of notifications arrives after long offline period","ui":"Group notifications by type — do not flood notification centre. Show: ''You have 12 new activity notifications'' as single grouped item. Expand to see all. Never send 12 individual pushes on reconnect."},{"trigger":"Notification settings sync fails across devices","ui":"Settings saved locally first, synced to server. If sync fails: local preference honoured. Show sync error badge in settings. Retry on next app open. Never lose user preference."}],"edge_cases":[{"case":"User has notifications enabled but device is in Do Not Disturb","ui":"No special handling needed — OS handles DND. Never override OS-level DND for non-critical notifications. Only critical alerts (transaction failures, security alerts) may use high-priority channel."},{"case":"Notification for content the user has already seen","ui":"Mark notification as read automatically if user has already viewed the linked content. Badge count decrements. Never show notification as unread for already-seen content."},{"case":"User taps notification while already on the linked screen","ui":"Refresh the current screen content instead of re-navigating. No animation flash or stutter. Subtle refresh indicator only."},{"case":"Notification settings differ between web and mobile","ui":"Show separate toggles for each platform in notification settings. Changes to one do not affect the other. Clear labels: ''Mobile push'' vs ''Email'' vs ''In-app''."},{"case":"Notification for action completed by a different device","ui":"Still show notification if it carries new information (e.g. order shipped). Suppress notification if it is purely confirmatory of an action the user just took on this device (e.g. ''login successful'' after login)."}]}'::jsonb, 6),
  ('payments', 'Payments', 'In-app payment collection — cards, wallets, invoices, and payouts.', 'credit-card', '{}', '{"feature_id":"payments","feature_name":"Payments","description":"In-app payment collection — cards, wallets, invoices, and payouts.","screens_added":[{"id":"payment_method_setup","name":"Add Payment Method","purpose":"Card or wallet addition"},{"id":"checkout","name":"Checkout","purpose":"Order summary + payment confirmation"},{"id":"payment_success","name":"Payment Success","purpose":"Confirmation screen post-payment"},{"id":"transaction_history","name":"Transaction History","purpose":"All payments made by user"},{"id":"invoice_detail","name":"Invoice / Receipt","purpose":"Single transaction detail and download"},{"id":"payout_settings","name":"Payout Settings","purpose":"For seller/provider — bank account + payout schedule"}],"entities_added":["Payment","Card","Invoice","Refund","Payout","Subscription"],"flows_added":["Add card → verify → save → use at checkout","Checkout → select payment method → confirm → biometric → success","Request refund → select reason → submit → status tracking","Provider payout → view earnings → request payout → bank transfer"],"interaction_patterns":["Biometric confirmation on every payment action","Card number input — auto-formats with spaces every 4 digits","Large numeric keypad for amount entry — never standard keyboard","Security confirmation step always before money movement","Success screen — confetti or pulse animation on payment complete","Debit shown in red, credit in green — always"],"generates_images":false,"error_flows":[{"trigger":"Card declined","ui":"Inline error below payment method: ''Card declined — please check your details or try a different card''. Red border on card fields. Specific decline reason if available (insufficient funds vs card blocked). Order NOT created. Cart fully preserved. Retry without re-entering entire form."},{"trigger":"3DS / bank verification fails","ui":"Return from bank verification to checkout with message: ''Verification failed — your bank did not approve this payment''. Try different card CTA. Explain that no charge was made. Never leave user on a blank redirect."},{"trigger":"Payment times out","ui":"After 30 seconds: spinner replaced with: ''This is taking longer than expected''. After 60 seconds: ''Payment timed out — please try again''. Show whether charge was made. If unknown: ''Check your bank before retrying to avoid double charge''."},{"trigger":"Payout fails for seller/provider","ui":"In earnings screen: amber badge ''Payout failed''. Reason shown: invalid bank details, account verification needed. CTA: ''Update bank details''. Retry scheduled automatically once fixed. Funds held safely — never lost."},{"trigger":"Refund request fails","ui":"Toast: ''Refund could not be processed at this time''. Estimated retry time shown. Support contact CTA. Never tell user refund was successful before it is confirmed."},{"trigger":"Subscription renewal fails","ui":"Push notification: ''Payment failed for your subscription''. Grace period shown: ''Your access continues for X days''. CTA: ''Update payment method''. After grace period: downgrade to free, not full lockout."}],"edge_cases":[{"case":"User attempts to pay with expired card","ui":"Expired badge on saved card. Expired card cannot be selected as payment method. Prompt to add new card. Never allow selection and fail at confirmation."},{"case":"Partial refund on a multi-item order","ui":"Show itemised refund breakdown. Clearly show which items are refunded and which are not. Total refund amount prominently displayed. Timeline shown."},{"case":"Payment made in wrong currency","ui":"Before confirming: show exact amount in user''s local currency with exchange rate. Timestamp rate. ''Charged in [currency] — converted at [rate] on [date]'' always visible on receipt."},{"case":"Duplicate payment submitted (double tap)","ui":"Payment button disabled immediately on first tap. Subsequent taps ignored silently. Idempotency key used on backend. If duplicate charge occurs: auto-refund and notify."},{"case":"Free trial ends while user is mid-session","ui":"Non-intrusive banner: ''Your free trial has ended''. Do not interrupt current action. On next significant action: paywall shown with upgrade CTA. Never mid-flow modal that blocks current task."},{"case":"Promo code applied but discount not reflected","ui":"Show code as applied with green tick. If discount not calculating: ''Code applied but no eligible items in cart''. Specific reason if possible. Never silently fail."}]}'::jsonb, 7),
  ('search_filters', 'Search & Filters', 'Full-text search with filtering, sorting, and saved search support.', 'search', '{}', '{"feature_id":"search_filters","feature_name":"Search & Filters","description":"Full-text search with filtering, sorting, and saved search support.","screens_added":[{"id":"search_home","name":"Search","purpose":"Search bar, recent searches, trending"},{"id":"search_results","name":"Search Results","purpose":"Results list with filter and sort controls"},{"id":"filter_panel","name":"Filter Panel","purpose":"Advanced filter options — slides up from bottom"}],"entities_added":["SearchQuery","SearchResult","Filter","SavedSearch"],"flows_added":["Tap search bar → type query → live results → tap result","Search results → open filter panel → apply filters → refined results","Save search → get notified when new results match"],"interaction_patterns":["Live search — results update as user types, no submit needed","Recent searches shown on empty state — tap to re-run","Filter panel slides up from bottom as sheet","Active filter chips shown below search bar — tap to remove","Result count updates in real time as filters change","Clear all filters — single tap resets to unfiltered results"],"generates_images":false,"error_flows":[{"trigger":"Search returns zero results","ui":"Illustration of empty search. Query shown in message: ''No results for \"[query]\"''. Suggestions: check spelling, try fewer words, browse categories. Show 3–5 related or trending searches. Never show empty white screen."},{"trigger":"Search times out or fails","ui":"Message: ''Search is taking too long — please try again''. Retry button. If repeated failure: ''Search is temporarily unavailable''. Show browse categories as fallback. Never show spinner indefinitely."},{"trigger":"Filter combination returns zero results","ui":"Show count updating in real time as filters are applied. When count reaches zero: warn before applying: ''No results match all these filters''. Highlight which filter is most restrictive. Suggest removing one filter."},{"trigger":"Saved search no longer returns results","ui":"In saved searches: amber badge ''No current results''. Last result count and date shown. ''Update filters'' CTA. Do not delete saved search automatically — user may want to keep for future."},{"trigger":"Search index temporarily out of sync","ui":"Show results with note: ''Results may not include the most recent updates''. Timestamp of last index shown. Never show stale data without disclosure."}],"edge_cases":[{"case":"Search query contains special characters or SQL-like strings","ui":"Sanitize silently — never show error for user input. Treat as plain text search. Never expose that sanitization occurred."},{"case":"User applies contradictory filters (e.g. price min > price max)","ui":"Auto-correct: swap min and max silently. Or: show inline warning on the contradicting field. Never allow search to run with logically impossible filter combination."},{"case":"Very long search query (200+ characters)","ui":"Accept and search. Truncate display in search bar to last 60 characters with ''...'' prefix. Full query used for search. Never silently truncate the actual search."},{"case":"User searches immediately after first app open (cold start)","ui":"Search index may not be warm. Show ''Searching...'' with skeleton results for up to 2 seconds before showing empty state. Never flash empty state before results have had time to load."},{"case":"Filter options change after user has saved a filter set","ui":"On loading saved filter: check each filter option still exists. Silently drop invalid options. Show notice: ''Some saved filters are no longer available and have been removed''."},{"case":"Search with accented characters or non-Latin scripts","ui":"Normalize search input — ''café'' matches ''cafe''. Support right-to-left display for Arabic/Hebrew queries. Results sort correctly regardless of script."}]}'::jsonb, 8),
  ('video_calls', 'Video / Calls', 'Voice and video calling between users with call management and history.', 'video', '{}', '{"feature_id":"video_calls","feature_name":"Video / Calls","description":"Voice and video calling between users with call management and history.","screens_added":[{"id":"call_incoming","name":"Incoming Call","purpose":"Full-screen incoming call with accept and decline"},{"id":"active_call","name":"Active Call","purpose":"Voice or video call screen with controls"},{"id":"call_history","name":"Call History","purpose":"All past calls — missed, incoming, outgoing"},{"id":"call_settings","name":"Call Settings","purpose":"Audio, video, and notification preferences for calls"}],"entities_added":["Call","CallParticipant","CallRecording"],"flows_added":["Initiate call → ring → recipient accepts → connected → end call → summary","Receive incoming call → full-screen overlay → accept or decline","Voice call → upgrade to video → switch camera → mute → end"],"interaction_patterns":["Incoming call — full-screen overlay, never a banner","Mute — fills with red when active, always visible","Camera toggle — indicator always shows whether camera is on","Speaker toggle — prominent, especially for voice calls","End call — always red, always in the same position","Call duration timer — always visible during active call","Tap to show or hide controls during video call"],"generates_images":false,"error_flows":[{"trigger":"Camera or microphone permission denied","ui":"Can not join with video/audio. Show specific missing permission. CTA: direct link to browser/device settings. Option: ''Join without camera'' if audio-only is acceptable. Never silently join muted with no camera — be explicit about state."},{"trigger":"Poor connection during call","ui":"Connection quality indicator in corner: green/amber/red bars. At amber: ''Your connection is unstable — the other person may experience issues''. At red: ''Poor connection — switching to audio only''. Auto-degrade video quality before dropping to audio."},{"trigger":"Call drops unexpectedly","ui":"Full-screen: ''Call disconnected''. Duration shown. Rejoin button. Option to call back. If all parties dropped: show who was on the call. Never return to home screen silently."},{"trigger":"Other party''s camera or mic fails mid-call","ui":"Show video placeholder with their name and camera-off icon. Audio indicator still shows if they''re speaking. Never show frozen last frame as if still live."},{"trigger":"Call fails to connect (ring timeout)","ui":"After 30 seconds no answer: ''No answer''. CTA: ''Try again'' or ''Send a message''. Call logged in history as ''Missed''. Never show endless ringing with no timeout."},{"trigger":"Recording fails to save","ui":"End of call: ''Recording could not be saved — storage issue''. Explain why if possible. If recording was promised to participants: notify all that recording is unavailable. Never silently lose a recording."}],"edge_cases":[{"case":"User joins call from multiple devices simultaneously","ui":"Second device shows: ''You are already in this call on another device. Join here and disconnect the other?'' Explicit choice. Never allow silent multi-device join — audio echo risk."},{"case":"Call scheduled but organiser hasn''t joined yet","ui":"Waiting room shows: ''Waiting for [organiser name] to start the call''. Timer showing how long since scheduled start. Leave option always available. Never strand participants indefinitely."},{"case":"Group call where all but one participant leaves","ui":"Show: ''Everyone else has left the call''. Options: ''End call'' or ''Stay on''. Auto-end after 60 seconds with no action. Never leave user on an empty call indefinitely."},{"case":"Screen share shows sensitive content accidentally","ui":"Screen share always requires explicit start confirmation: ''You are about to share your entire screen — make sure no sensitive content is visible''. Stop sharing button always prominent during share."},{"case":"Incoming call while user is already on a call","ui":"Incoming call banner at top: caller name and decline/hold-and-answer options. Never auto-answer second call. First call put on hold explicitly, not silently."},{"case":"Call participant uses a very slow device (high CPU)","ui":"Auto-reduce received video quality for that participant. Their feed stays visible but at lower resolution. Never cause their app to crash by sending too high a stream."}]}'::jsonb, 9);

COMMIT;
